package com.ckchoi.yesss24;
import org.json.*;
import java.util.*;
public final class SessionCodec {
 public static String value(JSONObject o,String... keys) { if(o==null)return ""; for(String k:keys){Object v=o.opt(k); if(v!=null&&v!=JSONObject.NULL&&!v.toString().trim().isEmpty()&&!"null".equals(v.toString()))return v.toString();} return ""; }
 public static JSONObject unwrap(JSONObject o){for(String k:new String[]{"data","result"})if(o.optJSONObject(k)!=null)return o.optJSONObject(k);return o;}
 public static JSONArray devices(Object o) throws JSONException {JSONArray a=new JSONArray(); collect(o,a); LinkedHashMap<String,JSONObject> unique=new LinkedHashMap<>(); for(int i=0;i<a.length();i++){JSONObject d=a.getJSONObject(i);String id=value(d,"deviceId","DeviceId");if(!id.isEmpty())unique.putIfAbsent(id,d);}return new JSONArray(unique.values());}
 private static void collect(Object o,JSONArray out)throws JSONException {if(o instanceof JSONObject j){Iterator<String> it=j.keys();while(it.hasNext()){String k=it.next();Object v=j.opt(k);if((k.equalsIgnoreCase("deviceList")||k.equalsIgnoreCase("devices"))&&v instanceof JSONArray arr){for(int i=0;i<arr.length();i++){JSONObject d=arr.optJSONObject(i);if(d==null)continue;JSONObject copy=new JSONObject(d.toString());for(String nested:new String[]{"device","deviceInfo"}){JSONObject n=d.optJSONObject(nested);if(n!=null){Iterator<String> ni=n.keys();while(ni.hasNext()){String nk=ni.next();copy.put(nk,n.get(nk));}}}out.put(copy);}}else if(v instanceof JSONObject||v instanceof JSONArray)collect(v,out);}}else if(o instanceof JSONArray a){for(int i=0;i<a.length();i++)collect(a.opt(i),out);}}
 public static JSONObject parse(JSONObject raw,String fallbackUser)throws JSONException {JSONObject s=unwrap(raw),k=s.optJSONObject("kepub_Info");if(k==null)k=new JSONObject(); if(!s.optBoolean("success",s.optInt("resultCode")==100)||s.optInt("resultCode",100)!=100)throw new JSONException("앱 인증 실패 ("+s.optInt("resultCode")+")");String no=value(s,"user_No","userNo","UserNo");if(no.isEmpty())no=value(k,"userNo","UserNo");if(!no.matches("[1-9][0-9]*"))throw new JSONException("로그인 응답에 유효한 사용자 번호가 없습니다.");String user=value(s,"user_Id","userId");if(user.isEmpty())user=value(k,"userId");if(user.isEmpty())user=fallbackUser;String token=value(s,"auth_Token","authToken","token");if(token.isEmpty())throw new JSONException("앱 인증 토큰이 없습니다.");JSONObject device=k.optJSONObject("deviceInfo");JSONArray list=devices(k);if(device==null&&list.length()>0)device=list.getJSONObject(0);if(device==null||value(device,"deviceId").isEmpty())throw new JSONException("인증된 기기 정보가 없습니다.");return new JSONObject().put("userId",user).put("userNo",no).put("token",token).put("device",device).put("devices",list); }
}
